  ("reaccion", "gancho", "regañar", "«Mejor me callo»", "burbuja de chat que se apaga"),
  ("titular", "intro", "El hogar cristiano", "El hogar cristiano · Elena G. de White", "portada genérica de libro con casa estilizada"),
  ("cita", "porque", "Entre la infancia", "«Entre la infancia y la edad adulta, los hijos no reciben generalmente la atención que debiera concedérseles.» — El hogar cristiano, cap. 31", "línea de tiempo con un tramo resaltado"),
  ("titular", "i1", "sé su confidente", "1 · Sé su confidente", "ícono de dos globos de diálogo"),
  ("ideas", "i1", "penas", "Que te cuenten sus penas del día\nSin simpatía en casa, la buscarán afuera", "ícono de oído atento"),
  ("cita", "i1", "confianza", "«Enseñadles a hacer de vosotros sus confidentes.» — El hogar cristiano, cap. 30", "ícono de llave"),
  ("reaccion", "papa", "importante", "«¡No es para tanto!»", "ícono de signo de exclamación grande"),
  ("reaccion", "teen", "Para mí", "«Para mí sí lo es.»", "burbuja pequeña que se encoge"),
