  ("titular", "i3", "firmeza sin dureza", "3 · Firmeza sin dureza", "ícono de escudo con corazón"),
  ("ideas", "i3", "autoridad", "Autoridad + afecto\nNo soltar la regla\nMás cariño cuando es más difícil", "regla y corazón unidos"),
  ("titular", "i4", "tu voz", "4 · Tu voz marca el clima", "ícono de termómetro con onda de sonido"),
  ("ideas", "i4", "amabilidad", "Hablar con amabilidad\nSin voz áspera\nConservar la calma", "onda de voz que se suaviza"),
  ("accion", "accion", "diez minutos", "Esta semana: 10 minutos sin pantallas. Solo escuchar.", "reloj de 10 min con teléfono boca abajo"),
