  ("titular", "gancho", "Confía", "Ya no soy un niño. Confía en mí.", "ícono de llave entregada de una mano a otra"),
  ("titular", "intro", "La educación", "La educación · Elena G. de White", "portada genérica de libro con birrete"),
  ("cita", "porque", "El propósito de la disciplina", "«El propósito de la disciplina es educar al niño para que se gobierne solo.» — La educación, cap. 34", "timón de barco"),
  ("titular", "i1", "guía la voluntad", "1 · Guía la voluntad, no la aplastes", "brote que crece contra una mano que lo presiona"),
  ("ideas", "i1", "sumisión aparente", "Fuerza: sumisión aparente\nSin control externo, no sabe usar su libertad", "jaula abierta"),
  ("reaccion", "papa", "celular", "«¡Enséñame ese celular!»", "ícono de teléfono con ojo vigilante"),
  ("reaccion", "teen", "confías", "«¿Es que no confías en mí?»", "burbuja de diálogo rota"),
  ("titular", "i2", "confianza, no sospecha", "2 · Confianza, no sospecha", "ícono de apretón de manos"),
  ("cita", "i2", "La sospecha", "«La sospecha desmoraliza y produce los mismos males que trata de impedir.» — La educación, cap. 34", "ícono de lupa tachada"),
  ("titular", "i3", "pedir que ordenar", "3 · Mejor pedir que ordenar", "mano abierta con signo de interrogación"),
  ("ideas", "i3", "pocas", "Pedir da espacio para decidir bien\nPocas reglas, bien pensadas", "lista corta con tres palomitas"),
  ("titular", "i4", "crítica constante", "4 · La crítica constante no reforma", "ícono de viento fuerte"),
